# hypothesis: A decorator typed as Callable[Concatenate[int, P], R] -> Callable[P, R] removes the injected int parameter, so callers must omit it while keyword arguments are still checked against P.
from collections.abc import Callable
from functools import wraps
from typing import Concatenate, assert_type, reveal_type


def with_attempt[**P, R](fn: Callable[Concatenate[int, P], R]) -> Callable[P, R]:
    @wraps(fn)
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(1, *args, **kwargs)
    return inner


@with_attempt
def fetch(attempt: int, url: str, *, timeout: float = 1.0) -> str:
    return f'{url}@{attempt}:{timeout}'


@with_attempt  # expect-error: first parameter str does not accept the injected int
def label(attempt: str, name: str) -> str:
    return attempt + name


def bad_timeout() -> str:
    return fetch('http://b', timeout='slow')  # expect-error: str is not float


reveal_type(fetch)
assert_type(fetch('http://a', timeout=2.5), str)
print(fetch('http://a', timeout=2.5))
print(bad_timeout())
try:
    print(label('n'))
except TypeError as exc:
    print('runtime:', type(exc).__name__)
